   770  /**
   771   * Encodes a coordinate on the sphere to the H3 index of the containing cell at
   772   * the specified resolution.
   773   *
   774   * Returns 0 on invalid input.
   775   *
   776   * @param g The spherical coordinates to encode.
   777   * @param res The desired H3 resolution for the encoding.
   778   * @param out The encoded H3Index.
   779   * @returns E_SUCCESS (0) on success, another value otherwise
   780   */
   781  H3Error H3_EXPORT(latLngToCell)(const LatLng *g, int res, H3Index *out) {
   782      if (res < 0 || res > MAX_H3_RES) {
   783          return E_RES_DOMAIN;
   784      }
   785      if (!isfinite(g->lat) || !isfinite(g->lng)) {
   786          return E_LATLNG_DOMAIN;
   787      }
   788
   789      FaceIJK fijk;
   790      _geoToFaceIjk(g, res, &fijk);
   791      *out = _faceIjkToH3(&fijk, res);
   792      if (*out) {
   793          return E_SUCCESS;
   794      } else {
   795          return E_FAILED;
   796      }
   797  }
