   832  /**
   833   * Convert an H3Index to a FaceIJK address.
   834   * @param h The H3Index.
   835   * @param fijk The corresponding FaceIJK address.
   836   */
   837  H3Error _h3ToFaceIjk(H3Index h, FaceIJK *fijk) {
   838      int baseCell = H3_GET_BASE_CELL(h);
   839      if (baseCell < 0 || baseCell >= NUM_BASE_CELLS) {  // LCOV_EXCL_BR_LINE
   840          // Base cells less than zero can not be represented in an index
   841          // To prevent reading uninitialized memory, we zero the output.
   842          fijk->face = 0;
   843          fijk->coord.i = fijk->coord.j = fijk->coord.k = 0;
   844          return E_CELL_INVALID;
   845      }
   846      // adjust for the pentagonal missing sequence; all of sub-sequence 5 needs
   847      // to be adjusted (and some of sub-sequence 4 below)
   848      if (_isBaseCellPentagon(baseCell) && _h3LeadingNonZeroDigit(h) == 5)
   849          h = _h3Rotate60cw(h);
   850
   851      // start with the "home" face and ijk+ coordinates for the base cell of c
   852      *fijk = baseCellData[baseCell].homeFijk;
   853      if (!_h3ToFaceIjkWithInitializedFijk(h, fijk))
   854          return E_SUCCESS;  // no overage is possible; h lies on this face
   855
   856      // if we're here we have the potential for an "overage"; i.e., it is
   857      // possible that c lies on an adjacent face
   858
   859      CoordIJK origIJK = fijk->coord;
   860
   861      // if we're in Class III, drop into the next finer Class II grid
   862      int res = H3_GET_RESOLUTION(h);
   863      if (isResolutionClassIII(res)) {
   864          // Class III
   865          _downAp7r(&fijk->coord);
   866          res++;
   867      }
   868
   869      // adjust for overage if needed
   870      // a pentagon base cell with a leading 4 digit requires special handling
   871      int pentLeading4 =
   872          (_isBaseCellPentagon(baseCell) && _h3LeadingNonZeroDigit(h) == 4);
   873      if (_adjustOverageClassII(fijk, res, pentLeading4, 0) != NO_OVERAGE) {
   874          // if the base cell is a pentagon we have the potential for secondary
   875          // overages
   876          if (_isBaseCellPentagon(baseCell)) {
   877              while (_adjustOverageClassII(fijk, res, 0, 0) != NO_OVERAGE)
   878                  continue;
   879          }
   880
   881          if (res != H3_GET_RESOLUTION(h)) _upAp7r(&fijk->coord);
   882      } else if (res != H3_GET_RESOLUTION(h)) {
   883          fijk->coord = origIJK;
   884      }
   885      return E_SUCCESS;
   886  }
